import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner is the test contract
        // set up: send 1 wei to the contract via fallback
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 wei}("");
        assertEq(address(c).balance, 1 wei);

        // call withdrawAll() - reference transfers all balance, modified does nothing
        c.withdrawAll();

        // now try to withdraw 1 wei - in reference, balance is 0 so transfer(0) works
        // in modified version, balance is still 1 wei, but we only try to withdraw 1 wei
        // Actually let's use a simpler scenario: after withdrawAll, reference balance = 0, modified balance = 1 wei
        // Then try to withdraw 1 wei from owner - reference will revert (transfer(1) when balance=0)
        // But modified will succeed (transfer(1) when balance=1)
        // So instead we check: after withdrawAll, is address(c).balance == 0?
        assertEq(address(c).balance, 0);
    }
}

