pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a recipient contract to observe sendMoney's effect
        address recipient = address(new Recipient());

        // Fund Alice as the owner
        address alice = address(0xABCD);
        vm.deal(alice, 10 ether);

        // Step 1: Alice deposits 1 ether via fallback
        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);

        // Step 2: Alice withdraws 0.5 ether
        vm.prank(alice);
        c.withdraw(0.5 ether);

        // Step 3: Alice calls sendMoney with 1 ether value
        vm.prank(alice);
        bool ok2;
        try c.sendMoney(recipient, 1 ether, "") {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(ok2);

        // The reference contract sends 1 ether to recipient and retains 0.5 ether.
        // The buggy contract sends 0 ether and retains 1.5 ether.
        // Assert that the contract's balance is less than 1.5 ether (i.e., not retaining all ethers)
        assertTrue(address(c).balance < 1.5 ether);
    }
}

contract Recipient {
    receive() external payable {}
    fallback() external payable {}
}

